Surface3D CharacterSurface(std::string_view name){
    auto has=[&](std::string_view value){return name.find(value)!=std::string_view::npos;};
    if(has("Metal")||has("Gold")||has("Buckle"))return{.22f,.82f,0,.96f};
    if(has("Eye")||has("Iris"))return{.16f,0,0,1};
    if(has("Hair"))return{.31f,0,0,.94f};
    if(has("Skin")||has("Face"))return{.43f,0,0,1};
    if(has("Lip"))return{.36f,0,0,1};
    if(has("Leather")||has("Boot"))return{.48f,0,0,.96f};
    return{.68f,0,0,1};
}

std::vector<Material3D> CharacterMaterials(const SkinnedModelAssetData& asset){
    std::vector<Material3D> result;result.reserve(asset.materialSlotNames.size());
    for(std::size_t slot=0;slot<asset.materialSlotNames.size();++slot){
        Material3D material;material.useUv=false;
        if(asset.materials.empty())material.surface=CharacterSurface(asset.materialSlotNames[slot]);
        else{const SkinnedMaterialDefinition3D& source=asset.materials[slot];material.tint=source.baseColorFactor;material.surface={source.roughnessFactor,source.metallicFactor,Clamp((std::max)({source.emissiveFactor.x,source.emissiveFactor.y,source.emissiveFactor.z})*source.emissiveStrength,0.f,1.f),source.occlusionStrength};material.normalScale=source.normalScale;material.alphaMode=source.alphaMode==SkinnedMaterialAlphaMode3D::Mask?MaterialAlphaMode3D::Mask:source.alphaMode==SkinnedMaterialAlphaMode3D::Blend?MaterialAlphaMode3D::Blend:MaterialAlphaMode3D::Opaque;material.alphaCutoff=source.alphaCutoff;material.doubleSided=source.doubleSided;}
        result.push_back(material);
    }
    return result;
}

std::vector<Material3D> LoadCharacterMaterials(Engine& engine,MaterialLibrary3D& library,const SkinnedModelAssetData& asset,const std::filesystem::path& materialRoot,const std::filesystem::path& sidecar){
    const SkinnedMaterialSidecarResult3D parsed=LoadSkinnedMaterialSidecarFile3D(sidecar,asset.materialSlotNames,materialRoot);
    if(!parsed)throw std::runtime_error("Character material sidecar failed: "+parsed.error.message);
    std::vector<MaterialAssetDefinition3D> definitions=parsed.materials;
    const std::vector<Material3D> sourceMaterials=CharacterMaterials(asset);
    for(std::size_t index=0;index<definitions.size();++index){const float textureScale=definitions[index].material.textureScale,baseTextureScale=definitions[index].material.baseTextureScale,detailTextureScale=definitions[index].material.detailTextureScale;const bool useUv=definitions[index].material.useUv,castsShadow=definitions[index].material.castsShadow,doubleSided=definitions[index].material.doubleSided;const CharacterShadingModel3D shadingModel=definitions[index].material.shadingModel;const MaterialAlphaMode3D alphaMode=definitions[index].material.alphaMode;const float alphaCutoff=definitions[index].material.alphaCutoff;definitions[index].material=sourceMaterials[index];definitions[index].material.textureScale=textureScale;definitions[index].material.baseTextureScale=baseTextureScale;definitions[index].material.detailTextureScale=detailTextureScale;definitions[index].material.useUv=useUv;definitions[index].material.castsShadow=castsShadow;definitions[index].material.shadingModel=shadingModel;definitions[index].material.alphaMode=alphaMode;definitions[index].material.alphaCutoff=alphaCutoff;definitions[index].material.doubleSided=doubleSided;}
    if(!library.Initialize(engine,materialRoot)||!library.LoadAll(definitions))throw std::runtime_error("Character PBR texture batch loading failed");
    std::vector<Material3D> result;result.reserve(asset.materialSlotNames.size());for(const std::string& name:asset.materialSlotNames){const Material3D* material=library.Find(name);if(!material)throw std::runtime_error("Character PBR material binding failed: "+name);result.push_back(*material);}return result;
}

void AppendSkinnedPart(SkinnedModel3D& model,const Mesh3D& source,Vec3 position,Vec3 scale,std::uint16_t joint,Color color){
    const Matrix4 transform=CreateTransformMatrix(position,{},scale),normalTransform=CreateNormalMatrix(transform);const std::uint32_t base=std::uint32_t(model.bindMesh.vertices.size());model.bindMesh.vertices.reserve(model.bindMesh.vertices.size()+source.vertices.size());model.influences.reserve(model.influences.size()+source.vertices.size());
    for(const Vertex3D& vertex:source.vertices){const Vec3 point=TransformPoint(transform,{vertex.x,vertex.y,vertex.z});const Vec4 packed=UnpackNormalSnorm8(vertex.normal);const Vec3 normal=TransformNormal(normalTransform,{packed.x,packed.y,packed.z});model.bindMesh.vertices.push_back({point.x,point.y,point.z,PackNormalSnorm8(normal,packed.w),PackColorRgba8(color),vertex.u,vertex.v});SkinInfluences3D influences{};influences.joints[0]=joint;influences.weights[0]=65535;model.influences.push_back(influences);}
    model.bindMesh.indices.reserve(model.bindMesh.indices.size()+source.indices.size());for(std::uint32_t index:source.indices)model.bindMesh.indices.push_back(base+index);
}

std::size_t FindJoint(std::span<const std::string> names,std::string_view name){const auto found=std::find(names.begin(),names.end(),name);if(found==names.end())throw std::runtime_error("Required equipment joint is missing: "+std::string(name));return std::size_t(found-names.begin());}

Vec3 BindJointPosition(const Skeleton3D& skeleton,std::size_t joint){std::vector<Matrix4> globals(skeleton.joints.size());for(std::size_t index=0;index<skeleton.joints.size();++index){const Matrix4 local=skeleton.joints[index].bindTransform.Matrix();const int parent=skeleton.joints[index].parent;globals[index]=parent<0?local:globals[std::size_t(parent)]*local;}return TransformPoint(globals[joint],{});}

enum class EquipmentShape {Shoulder,Sword,Axe};
SkinnedModel3D CreateEquipmentModel(const SkinnedModel3D& character,std::size_t joint,EquipmentShape shape){
    SkinnedModel3D model;model.skeleton=character.skeleton;model.inverseBindMatrices=character.inverseBindMatrices;model.skeletonCompatibilityId=character.skeletonCompatibilityId;const Vec3 anchor=BindJointPosition(character.skeleton,joint);const Mesh3D box=Mesh3D::CreateUnitBox();
    if(shape==EquipmentShape::Shoulder){const Mesh3D dome=Mesh3D::CreateUnitSphere(16,10);AppendSkinnedPart(model,dome,anchor+Vec3{.08f,.02f,0},{.24f,.13f,.25f},std::uint16_t(joint),{.32f,.36f,.42f,1});AppendSkinnedPart(model,box,anchor+Vec3{.16f,-.08f,0},{.10f,.08f,.20f},std::uint16_t(joint),{.14f,.17f,.21f,1});}
    else if(shape==EquipmentShape::Sword){AppendSkinnedPart(model,box,anchor+Vec3{0,-.30f,.02f},{.065f,.44f,.028f},std::uint16_t(joint),{.68f,.73f,.78f,1});AppendSkinnedPart(model,box,anchor+Vec3{0,.10f,.02f},{.20f,.035f,.055f},std::uint16_t(joint),{.34f,.2f,.07f,1});AppendSkinnedPart(model,box,anchor+Vec3{0,.18f,.02f},{.04f,.10f,.04f},std::uint16_t(joint),{.18f,.09f,.035f,1});}
    else{AppendSkinnedPart(model,box,anchor+Vec3{0,-.18f,.02f},{.035f,.38f,.035f},std::uint16_t(joint),{.26f,.14f,.055f,1});AppendSkinnedPart(model,box,anchor+Vec3{.07f,-.47f,.02f},{.18f,.12f,.05f},std::uint16_t(joint),{.42f,.46f,.5f,1});}
    return model;
}

