std::uint64_t PoseHash(const AnimationPose3D& pose){std::uint64_t hash=14695981039346656037ull;for(const auto& transform:pose.localTransforms){const float values[]={transform.translation.x,transform.translation.y,transform.translation.z,transform.rotation.x,transform.rotation.y,transform.rotation.z,transform.quaternion.x,transform.quaternion.y,transform.quaternion.z,transform.quaternion.w};for(float value:values){const auto* bytes=reinterpret_cast<const unsigned char*>(&value);for(std::size_t i=0;i<sizeof(value);++i){hash^=bytes[i];hash*=1099511628211ull;}}}return hash;}
Quaternion3D MultiplyQuaternion(Quaternion3D a,Quaternion3D b){return NormalizeQuaternion3D({a.w*b.x+a.x*b.w+a.y*b.z-a.z*b.y,a.w*b.y-a.x*b.z+a.y*b.w+a.z*b.x,a.w*b.z+a.x*b.y-a.y*b.x+a.z*b.w,a.w*b.w-a.x*b.x-a.y*b.y-a.z*b.z});}
